import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    d = {}
    for i in range(n):
        name = data[1 + 3 * i]
        t = int(data[2 + 3 * i])
        l = int(data[3 + 3 * i])
        d.setdefault(name, []).append((t, l))
    cnt = 0
    for v in d.values():
        v.sort()
        up = down = False
        for i in range(1, len(v)):
            if v[i][1] > v[i - 1][1]:
                up = True
            elif v[i][1] < v[i - 1][1]:
                down = True
        if up and down:
            cnt += 1
    print(cnt)

